check-if-numbers-are-ascending-in-a-sent:
class Solution:
    def areNumbersAscending(self, s: str) -> bool:
        prev = -1
        for t in s.split():
            if t.isdigit():
                v = int(t)
                if v <= prev: return False
                prev = v
        return True

sum-of-digits-of-string-after-convert:
class Solution:
    def getLucky(self, s: str, k: int) -> int:
        n = ''.join(str(ord(c)-96) for c in s)
        for _ in range(k):
            n = str(sum(int(d) for d in n))
        return int(n)

determine-color-of-a-chessboard-square:
class Solution:
    def squareIsWhite(self, coordinates: str) -> bool:
        c, r = coordinates[0], int(coordinates[1])
        return (ord(c)-97 + r) % 2 == 1

maximum-number-of-words-found-in-sentenc:
class Solution:
    def mostWordsFound(self, sentences: List[str]) -> int:
        return max(s.count(' ') + 1 for s in sentences)

split-a-string-in-balanced-strings:
class Solution:
    def balancedStringSplit(self, s: str) -> int:
        ans = bal = 0
        for c in s:
            bal += 1 if c == 'L' else -1
            if bal == 0: ans +=  1
        return ans

xor-operation-in-an-array:
class Solution:
    def xorOperation(self, n: int, start: int) -> int:
        r =  0
        for i in range(n):
            r ^= start + 2*i
        return r

decode-xored-array:
class Solution:
    def decode(self, encoded: List[int], first: int) -> List[int]:
        res = [first]
        for x in encoded:
            res.append(res[-1] ^ x)
        return res

count-odd-numbers-in-an-interval-range:
class Solution:
    def countOdds(self, low: int, high: int) -> int:
        return (high+1)//2 - low//2

sign-of-the-product-of-an-array:
class Solution:
    def arraySign(self, nums: List[int]) -> int:
        neg = 0
        for x in nums:
            if x == 0: return 0
            if x < 0: neg +=  1
        return -1 if neg % 2 else 1

check-distances-between-same-letters:
class Solution:
    def checkDistances(self, s: str, distance: List[int]) -> bool:
        first = {}
        for i, c in enumerate(s):
            if c in first:
                if i - first[c] - 1 != distance[ord(c)-97]: return False
            else:
                first[c] = i
        return True

longest-subsequence-with-limited-sum:
class Solution:
    def answerQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        nums.sort()
        pref = [0]
        for x in nums: pref.append(pref[-1]+x)
        res = []
        for q in queries:
            lo, hi = 0, len(pref)-1
            while lo <= hi:
                mid = (lo+hi)//2
                if pref[mid] <= q: lo = mid+1
                else: hi = mid-1
            res.append(hi)
        return res

minimum-number-of-moves-to-seat-everyone:
class Solution:
    def minMovesToSeat(self, seats: List[int], students: List[int]) -> int:
        seats.sort(); students.sort()
