most-frequent-number-following-key-in-an:
class Solution:
    def mostFrequent(self, nums: List[int], key: int) -> int:
        from collections import Counter
        targets = [nums[i+1] for i in range(len(nums)-1) if nums[i] == key]
        if not targets: return -1
        return Counter(targets).most_common(1)[0][0]

maximum-units-on-a-truck:
class Solution:
    def maximumUnits(self, boxTypes: List[List[int]], truckSize: int) -> int:
        boxTypes.sort(key=lambda x: -x[1])
        ans =  0
        for count, units in boxTypes:
            take = min(count, truckSize)
            ans += take*units
            truckSize -= take
            if truckSize == 0: break
        return ans

min-max-game:
class Solution:
    def minMaxGame(self, nums: List[int]) -> int:
        while len(nums) > 1:
            nxt = []
            for i in range(len(nums)//2):
                if i % 2 ==  0:
                    nxt.append(min(nums[2*i], nums[2*i+1]))
                else:
                    nxt.append(max(nums[2*i], nums[2*i+1]))
            nums = nxt
        return nums[0]

maximum-ascending-subarray-sum:
class Solution:
    def maxAscendingSum(self, nums: List[int]) -> int:
        best = cur = nums[0]
        for i in range(1, len(nums)):
            if nums[i] > nums[i-1]:
                cur += nums[i]
            else:
                cur = nums[i]
            best = max(best, cur)
        return best
